  "sql": "WITH _base AS (\n  SELECT\n    customers.tier AS \"customers.tier\",\n    COUNT(*) AS \"customers.customers\"\n  FROM customers AS customers\n  GROUP BY\n    customers.tier\n), _cm_customers__orders__id_count AS (\n  SELECT\n    customers.tier AS \"orders.customers.tier\",\n    COUNT(orders.id) AS \"orders.id_count\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  GROUP BY\n    customers.tier\n)\nSELECT\n  _base.\"customers.tier\",\n  _base.\"customers.customers\",\n  COALESCE(_cm_customers__orders__id_count.\"orders.id_count\", 0) AS \"customers.orders\",\n  COALESCE(_cm_customers__orders__id_count.\"orders.id_count\", 0) / NULLIF(_base.\"customers.customers\", 0) AS \"customers.avg_orders\"\nFROM _base\nLEFT JOIN _cm_customers__orders__id_count\n  ON _base.\"customers.tier\" IS NOT DISTINCT FROM _cm_customers__orders__id_count.\"orders.customers.tier\"\nORDER BY\n  _base.\"customers.tier\" ASC\nLIMIT 101"
